import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Login = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    const result = await login(username, password);
    setLoading(false);
    if (result.success) {
      navigate('/dashboard');
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.box}>
        <div style={styles.icon}>🌐</div>
        <h1 style={styles.title}>ISP Management</h1>
        <p style={styles.subtitle}>Sign in to your account</p>
        <form onSubmit={handleSubmit}>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Username</label>
            <input
              type="text"
              placeholder="Enter username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              style={styles.input}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Password</label>
            <input
              type="password"
              placeholder="Enter password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={styles.input}
              required
            />
          </div>
          <button type="submit" disabled={loading} style={styles.button}>
            {loading ? 'Loading...' : 'Sign In'}
          </button>
        </form>
        <p style={styles.hint}>Default: admin / admin123</p>
      </div>
    </div>
  );
};

const styles = {
  container: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '100vh',
    background: '#f0f4f9',
  },
  box: {
    background: 'white',
    padding: '40px',
    borderRadius: '20px',
    boxShadow: '0 20px 60px rgba(0,0,0,0.1)',
    width: '400px',
    maxWidth: '95%',
  },
  icon: {
    textAlign: 'center',
    fontSize: '48px',
    marginBottom: '12px',
  },
  title: {
    textAlign: 'center',
    fontSize: '26px',
    margin: '0 0 8px 0',
    color: '#1a2a3a',
  },
  subtitle: {
    textAlign: 'center',
    color: '#6b7f99',
    marginBottom: '28px',
  },
  inputGroup: {
    marginBottom: '16px',
  },
  label: {
    display: 'block',
    fontWeight: '600',
    marginBottom: '4px',
    color: '#1a2a3a',
    fontSize: '14px',
  },
  input: {
    width: '100%',
    padding: '12px 16px',
    border: '2px solid #e2eaf2',
    borderRadius: '10px',
    fontSize: '15px',
    boxSizing: 'border-box',
  },
  button: {
    width: '100%',
    padding: '14px',
    background: '#2a7de1',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontSize: '16px',
    fontWeight: '600',
    cursor: 'pointer',
    transition: '0.2s',
    opacity: loading ? 0.7 : 1,
  },
  hint: {
    marginTop: '16px',
    textAlign: 'center',
    fontSize: '14px',
    color: '#6b7f99',
  },
};

export default Login;
